package org.transittr;
import java.io.*;import java.net.URLEncoder;import java.util.*;import org.json.*;
/** Public BursaKart transport API. Smart-station ETAs are separate from a selected line's fleet. */
public final class BursaClient {
 private static final String BASE="https://bursakartcoreapi.abys-web.com/";private static String key="",token="";private static long expires;
 public static void init(android.content.Context context){try{InputStream in=context.getAssets().open("bursa-bootstrap.json");ByteArrayOutputStream out=new ByteArrayOutputStream();try{byte[] b=new byte[512];int n;while((n=in.read(b))!=-1){if(out.size()+n>8192)throw new IOException("Bursa yapılandırma sınırı");out.write(b,0,n);}}finally{in.close();}key=new JSONObject(new String(out.toByteArray(),"UTF-8")).getString("publicKey");}catch(Exception ignored){}}
 private static Map<String,String> headers()throws IOException{Map<String,String> h=new HashMap<String,String>();h.put("Content-Type","application/json");h.put("publicapikey",key);h.put("authkey",AsisAuth.generateOld());h.put("deviceid","transit-tr-anonymous");h.put("packagename","com.bursakart.burulas");h.put("version","430");h.put("versionname","2.2.20");h.put("operatingsystem","Android");h.put("buildvariant","production");h.put("language","tr");h.put("useragent","BursaKart/2.2.20");return h;}
 private static synchronized String token()throws IOException{if(token.length()>0&&System.currentTimeMillis()<expires)return token;try{JSONObject b=new JSONObject();b.put("publicApiKey",key);JSONObject d=new JSONObject(ApiHttp.text(BASE+"create/apitoken",b.toString().getBytes("UTF-8"),"application/json",headers(),32768));if(!d.optBoolean("success",false))throw new IOException("Bursa anonim erişimi alınamadı");token=d.getJSONObject("createApiTokenCommandResultDto").getString("token");expires=System.currentTimeMillis()+20*60000;return token;}catch(JSONException e){throw new IOException("Bursa erişim yanıtı okunamadı");}}
 public static JSONObject request(String path,JSONObject body)throws IOException{try{for(int attempt=0;attempt<2;attempt++){Map<String,String> h=headers();h.put("Authorization","Bearer "+token());JSONObject d=new JSONObject(ApiHttp.text(BASE+path,body==null?null:body.toString().getBytes("UTF-8"),"application/json",h,4194304));if(d.optBoolean("success",false))return d;if(attempt==0&&"1028".equals(d.optString("messageCode"))){synchronized(BursaClient.class){token="";}continue;}throw new IOException("Bursa servisi hata verdi ("+d.optString("messageCode")+")");}throw new IOException("Bursa erişimi yenilenemedi");}catch(JSONException e){throw new IOException("Bursa verisi okunamadı");}}
 private static JourneyData.Station station(JSONObject r){JourneyData.Station s=new JourneyData.Station(r.optString("description",r.optString("stationName","")),SourceTools.number(r,"latitude"),SourceTools.number(r,"longitude"));s.code=r.optString("stationId",r.optString("id",""));return s;}
 public static JSONObject search(String q)throws IOException{try{JSONObject b=new JSONObject();b.put("queryParam",q.length()==0?"19E":q);b.put("vehicleTypes",new JSONArray());b.put("stationTypes",new JSONArray());return request("alm/get/searchrouteandstations",b);}catch(JSONException e){throw new IOException("Bursa araması hazırlanamadı");}}
 public static JSONArray nearby(double lat,double lon)throws IOException{try{JSONArray a=request("alm/get/nearstations?latitude="+lat+"&longitude="+lon+"&radius=2000&count=50",null).getJSONArray("stations"),out=new JSONArray();for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i),n=new JSONObject();n.put("stopId",r.optString("stationId"));n.put("name",r.optString("description"));n.put("lat",r.optString("latitude"));n.put("lng",r.optString("longitude"));out.put(n);}return out;}catch(JSONException e){throw new IOException("Bursa yakın durakları okunamadı");}}
 public static JourneyData.Station stop(String code)throws IOException{try{JSONObject d=request("alm/get/stationbyid?StationId="+URLEncoder.encode(code,"UTF-8"),null);JSONObject r=d.optJSONObject("station");if(r==null){JSONArray a=d.optJSONArray("stations");if(a!=null&&a.length()>0)r=a.getJSONObject(0);}return r==null?null:station(r);}catch(JSONException e){throw new IOException("Bursa durağı okunamadı");}}
 private static JSONObject line(String code)throws IOException,JSONException{JSONArray rows=search(code).optJSONArray("routes");if(rows!=null)for(int i=0;i<rows.length();i++)if(code.equalsIgnoreCase(rows.getJSONObject(i).optString("routeCode")))return rows.getJSONObject(i);throw new IOException("Bursa hat kodu bulunamadı");}
 public static JourneyData.Snapshot query(String stop,String filter,boolean gps)throws IOException{try{JourneyData.Snapshot s=new JourneyData.Snapshot();s.source="BursaKart / BURULAŞ";s.separateMapRows=filter.length()>0;JSONArray rows=request("alm/get/smartstationinfo?StopId="+URLEncoder.encode(stop,"UTF-8"),null).optJSONArray("result");if(rows==null)throw new IOException("Bursa varış listesi yok");for(int i=0;i<rows.length()&&i<300;i++){JSONObject r=rows.getJSONObject(i);String code=r.optString("routeCode");if(!SourceTools.matches(code,filter))continue;JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="bursa:"+r.optString("licencePlate");v.line=code;v.name=r.optString("routeTitle");v.lat=SourceTools.number(r,"vehicleLat");v.lon=SourceTools.number(r,"vehicleLng");String time=r.optString("realTime","");if(time.matches("[0-9]{2}:[0-9]{2}:[0-9]{2}")){String[] p=time.split(":");long sec=Integer.parseInt(p[0])*3600+Integer.parseInt(p[1])*60+Integer.parseInt(p[2]);if(sec<86400)v.etaSeconds=sec;}v.eta=SourceTools.minutes(v.etaSeconds);v.arrivalStop=stop;v.etaIsStopArrival=v.etaSeconds>=0;s.rows.add(v);}
  if(gps&&filter.length()>0){try{JSONObject l=line(filter);JSONArray a=request("alm/get/routevehiclelocations?RouteNo="+l.getInt("routeNo"),null).optJSONArray("vehicleLocations");if(a!=null)for(int i=0;i<a.length()&&i<300;i++){JSONObject r=a.getJSONObject(i);JourneyData.Vehicle v=new JourneyData.Vehicle();v.id="bursa:"+r.optString("plate");v.line=r.optString("routeCode",filter);v.name=l.optString("routeDescription");v.lat=SourceTools.number(r,"latitude");v.lon=SourceTools.number(r,"longitude");v.sourceTime=r.optString("editDate");v.observedAt=SourceTools.time(v.sourceTime);v.eta="GPS";if(v.hasPosition())s.mapRows.add(v);}}catch(IOException failure){for(JourneyData.Vehicle v:s.rows)if(v.hasPosition())s.mapRows.add(v);s.message="Hat filo GPS servisi alınamadı; seçili durak için gelen varış ve GPS kayıtları korunuyor.";}}
  SourceTools.sort(s);if(s.rows.isEmpty())s.message="Seçilen durak ve hat için şu an varış kaydı yok.";return s;
 }catch(JSONException e){throw new IOException("Bursa canlı verisi okunamadı");}}
 public static JourneyData.Route route(String code,String name)throws IOException{try{JSONObject l=line(code);int n=l.getInt("routeNo");JourneyData.Route out=new JourneyData.Route();out.code=code;out.name=name;out.source="BursaKart / BURULAŞ";out.schematic=false;JSONArray points=request("alm/get/routecoordinate?routeNo="+n,null).getJSONArray("routeCoordinates");ArrayList<JourneyData.Station> part=new ArrayList<JourneyData.Station>();String direction="";for(int i=0;i<points.length()&&i<20000;i++){JSONObject r=points.getJSONObject(i);String d=r.optString("routeDirection");if(direction.length()==0)direction=d;if(!direction.equals(d))continue;part.add(station(r));}if(part.size()>1)out.parts.add(part);JSONArray stops=request("alm/get/routestations?RouteNo="+n,null).getJSONArray("stations");for(int i=0;i<stops.length()&&i<1000;i++){JSONObject r=stops.getJSONObject(i);JourneyData.Station s=station(r);out.stops.add(s);if(s.lat>=35&&s.lat<=43&&s.lon>=25&&s.lon<=45)out.mappedStops++;}return out;}catch(JSONException e){throw new IOException("Bursa güzergâhı okunamadı");}}
}
